def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = ""

        # Split pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse major.minor.patch
        parts = base.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(identifiers):
        # None means no pre-release (higher precedence)
        # Empty list means has pre-release
        if identifiers is None:
            return (1,)  # Higher sort value, so it comes after pre-release
        if not identifiers:
            return (0,)  # Lower sort value for pre-release with no identifiers

        result = [0]  # Mark as having pre-release
        for identifier in identifiers:
            if identifier.isdigit():
                result.append((0, int(identifier)))  # Numeric: (0, value)
            else:
                result.append((1, identifier))  # String: (1, value)
        return tuple(result)

    def sort_key(version_string):
        major, minor, patch, prerelease_identifiers = parse_version(version_string)

        # Convert empty list to None for easier comparison
        prerelease = prerelease_identifiers if prerelease_identifiers else None

        return (major, minor, patch, prerelease_sort_key(prerelease))

    # Sort using stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

